static bool SaveBmp(const wchar_t* path, const std::vector<BYTE>& rgba, UINT width, UINT height) {
    BITMAPFILEHEADER fh{}; BITMAPINFOHEADER ih{}; ih.biSize = sizeof(ih); ih.biWidth = static_cast<LONG>(width); ih.biHeight = -static_cast<LONG>(height); ih.biPlanes = 1; ih.biBitCount = 32; ih.biCompression = BI_RGB; ih.biSizeImage = width*height*4;
    fh.bfType = 0x4d42; fh.bfOffBits = sizeof(fh)+sizeof(ih); fh.bfSize = fh.bfOffBits+ih.biSizeImage;
    HANDLE file = CreateFileW(path, GENERIC_WRITE, 0, nullptr, CREATE_ALWAYS, FILE_ATTRIBUTE_NORMAL, nullptr); if (file == INVALID_HANDLE_VALUE) return false;
    DWORD wrote=0; bool ok=WriteFile(file,&fh,sizeof(fh),&wrote,nullptr)&&wrote==sizeof(fh); ok=ok&&WriteFile(file,&ih,sizeof(ih),&wrote,nullptr)&&wrote==sizeof(ih);
    std::vector<BYTE> bgra(rgba.size()); for(size_t i=0;i<rgba.size();i+=4){bgra[i]=rgba[i+2];bgra[i+1]=rgba[i+1];bgra[i+2]=rgba[i];bgra[i+3]=rgba[i+3];}
    ok=ok&&WriteFile(file,bgra.data(),static_cast<DWORD>(bgra.size()),&wrote,nullptr)&&wrote==bgra.size(); CloseHandle(file); return ok;
}
static void PrintHr(const wchar_t* what, HRESULT hr) { fwprintf(stderr,L"%ls failed: 0x%08lx\n",what,static_cast<unsigned long>(hr)); }

static int ValidateTextsMode(const wchar_t* dllPath, const wchar_t* textPath) {
    HMODULE dll=LoadLibraryW(dllPath);if(!dll){PrintHr(L"LoadLibrary",HRESULT_FROM_WIN32(GetLastError()));return 3;}
    auto initText=reinterpret_cast<InitializeText>(GetProcAddress(dll,"InitializeTextOverlay"));auto setCaption=reinterpret_cast<SetCaption>(GetProcAddress(dll,"SetCaptionUtf8"));
    if(!initText||!setCaption){fwprintf(stderr,L"dynamic text exports missing\n");FreeLibrary(dll);return 4;}
    HRESULT hr=initText();if(FAILED(hr)){PrintHr(L"InitializeTextOverlay",hr);FreeLibrary(dll);return 5;}
    if(setCaption("Linha 1\nLinha 2\nLinha 3\nLinha 4")!=S_OK){fwprintf(stderr,L"four-line boundary caption was rejected\n");FreeLibrary(dll);return 6;}
    if(setCaption("Linha 1\nLinha 2\nLinha 3\nLinha 4\nLinha 5")!=HRESULT_FROM_WIN32(ERROR_BUFFER_OVERFLOW)){fwprintf(stderr,L"five-line boundary caption was not rejected\n");FreeLibrary(dll);return 7;}
    std::string longWord(400,'W');if(setCaption(longWord.c_str())!=HRESULT_FROM_WIN32(ERROR_BUFFER_OVERFLOW)){fwprintf(stderr,L"overwide/unbroken word was not rejected\n");FreeLibrary(dll);return 8;}
    std::ifstream input{std::filesystem::path(textPath),std::ios::binary};if(!input){fwprintf(stderr,L"could not open text corpus\n");FreeLibrary(dll);return 9;}
    input.seekg(0,std::ios::end);std::streamoff size=input.tellg();if(size<0||size>1024*1024){fwprintf(stderr,L"corpus exceeds 1 MiB or could not be sized\n");FreeLibrary(dll);return 10;}input.seekg(0,std::ios::beg);
    std::string contents((std::istreambuf_iterator<char>(input)),std::istreambuf_iterator<char>());if(input.bad()){fwprintf(stderr,L"corpus read failed\n");FreeLibrary(dll);return 11;}
    size_t total=0,passed=0,failed=0,begin=0;
    while(begin<contents.size()){
        size_t end=contents.find('\n',begin);if(end==std::string::npos)end=contents.size();std::string line=contents.substr(begin,end-begin);begin=end==contents.size()?contents.size():end+1;if(!line.empty()&&line.back()=='\r')line.pop_back();
        ++total;HRESULT result=S_OK;if(total>479||line.size()>16000)result=HRESULT_FROM_WIN32(ERROR_BUFFER_OVERFLOW);else result=setCaption(line.c_str());
        if(SUCCEEDED(result))++passed;else{++failed;wprintf(L"index=%zu hresult=0x%08lx\n",total,static_cast<unsigned long>(result));}
    }
    wprintf(L"validate-texts total=%zu passed=%zu failed=%zu\n",total,passed,failed);FreeLibrary(dll);return failed?12:0;
}

